class Solution {
public:
    bool phonePrefix(vector<string>& numbers) {
        struct Node { unordered_map<char, Node*> nxt; bool end = false; };
        Node* root = new Node();
        for (auto& num : numbers) {
            Node* cur = root;
            for (char ch : num) {
                if (cur->end) return false;
                if (!cur->nxt.count(ch)) cur->nxt[ch] = new Node();
                cur = cur->nxt[ch];
            }
            if (!cur->nxt.empty()) return false;
            cur->end = true;
        }
        return true;
    }
};

