class Solution {
    public boolean phonePrefix(String[] numbers) {
        class Node { java.util.Map<Character, Node> nxt = new java.util.HashMap<>(); boolean end = false; }
        Node root = new Node();
        for (String num : numbers) {
            Node cur = root;
            for (char ch : num.toCharArray()) {
                if (cur.end) return false;
                cur.nxt.putIfAbsent(ch, new Node());
                cur = cur.nxt.get(ch);
            }
            if (!cur.nxt.isEmpty()) return false;
            cur.end = true;
        }
        return true;
    }
}

