var phonePrefix = function(numbers) {
    const END = '$';
    const root = {};
    for (const num of numbers) {
        let cur = root;
        for (const ch of num) {
            if (END in cur) return false;
            if (!(ch in cur)) cur[ch] = {};
            cur = cur[ch];
        }
        if (Object.keys(cur).length > 0) return false;
        cur[END] = true;
    }
    return true;
};
